var drop = new Border
{
    CornerRadius = new CornerRadius(16),
    BorderBrush = AppKit.Brush(ArcTokens.BorderStrong),
    BorderThickness = new Thickness(1),
    Padding = new Thickness(20, 26),
    Child = AppKit.Stack(6,
        AppKit.Disc("upload-cloud", 36, 17, true),
        new TextBlock { Text = "Drop files here or browse", Classes = { "arc-body-sm", "arc-medium" } },
        AppKit.Caption("PDF, PNG, JPG or DOCX up to 10 MB"))
};

var rows = new StackPanel { Spacing = 6 };
foreach (var upload in uploads)
{
    rows.Children.Add(AppKit.Row(10,
        new ArcIcon { Icon = upload.Type == "png" ? "image" : "file", Size = 16 },
        new TextBlock { Text = upload.Name, Classes = { "arc-body-sm" } },
        AppKit.Place(upload.State == UploadState.Uploading ? AppKit.Bar(upload.Progress / 100) : AppKit.Empty(), 1),
        upload.State == UploadState.Failed ? AppKit.Btn("Retry", ArcButtonVariant.Secondary) : AppKit.Caption("Done")));
}

return AppKit.Screen(AppKit.Stack(14, drop, rows), 474);
